// 1. Cryptographic HMAC SHA-256 Signature Verification
const crypto = require('crypto');

const req = $input.first().json;
const headers = req.headers || {};
const timestamp = headers['x-tabibi-timestamp'];
const signatureHeader = headers['x-tabibi-signature'];
const rawBody = req.rawBody || (typeof req.body === 'string' ? req.body : JSON.stringify(req.body));
const secret = process.env.N8N_SHARED_SECRET || 'tabibi_n8n_hmac_shared_secret_2026';

if (!timestamp || !signatureHeader) {
  throw new Error('401: Unauthorized - Missing Tabibi security headers');
}

const hmac = crypto.createHmac('sha256', secret);
hmac.update(`${timestamp}.${rawBody}`);
const expectedSignature = hmac.digest('hex');

const parts = signatureHeader.split(',');
const v1Part = parts.find(p => p.trim().startsWith('v1='));
const providedSignature = v1Part ? v1Part.trim().replace('v1=', '') : '';

if (!providedSignature || providedSignature !== expectedSignature) {
  throw new Error('401: Unauthorized - Invalid HMAC SHA-256 signature');
}

// 2. Extract Dynamic Tenant Context
const payload = typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
const tenant = payload.tenantConfiguration || {};
const doctorName = payload.doctorName || 'الدكتور';
const workingHours = tenant.workingHours || 'مواعيد العيادة';
const services = tenant.services || [];
const customPrompt = tenant.customSystemPrompt || '';
const messageText = payload.messageText || '';

return {
  json: {
    isValid: true,
    eventId: payload.eventId,
    clinicId: payload.clinicId,
    doctorId: payload.doctorId,
    doctorName,
    patientPhone: payload.patientPhone,
    messageText,
    workingHours,
    services,
    customPrompt
  }
};

// 3. Dynamic Tenant Response Processor (Zero Hardcoding)
const item = $input.first().json;
const msg = (item.messageText || '').toLowerCase();

const isPrice = msg.includes('سعر') || msg.includes('بكام') || msg.includes('كشف');
const isHours = msg.includes('مواعيد') || msg.includes('شغالين') || msg.includes('جمعة');

let replyText = `أهلاً بحضرتك في عيادة د. ${item.doctorName}. مواعيدنا: ${item.workingHours}. سعر الكشف ${item.services[0]?.price || 500} ج.م. تحب أساعدك تحجز ميعاد؟`;
let intent = 'GENERAL_INQUIRY';
let actionType = 'NONE';

if (isPrice && isHours) {
  replyText = `أهلاً بحضرتك! سعر الكشف مع د. ${item.doctorName} بـ ${item.services[0]?.price || 500} ج.م، ومواعيد العيادة ${item.workingHours}. تحب أساعدك تحجز ميعاد المناسب ليك؟`;
  intent = 'PRICES';
} else if (isPrice) {
  replyText = `أهلاً بك! سعر الكشف مع د. ${item.doctorName} هو ${item.services[0]?.price || 500} ج.م. تحب نسجلك حجز كشف؟`;
  intent = 'PRICES';
} else if (isHours) {
  replyText = `أهلاً بحضرتك! مواعيد د. ${item.doctorName} هي ${item.workingHours}. تحب تحجز ميعاد بكرة أو يوم تاني؟`;
  intent = 'WORKING_HOURS';
} else if (msg.includes('احجز') || msg.includes('حجز')) {
  replyText = `تمام! اختر ميعاد الكشف المناسب لك مع د. ${item.doctorName}:
1. بكرة الساعة 6:00 مساءً
2. الخميس الساعة 7:00 مساءً`;
  intent = 'BOOK_APPOINTMENT';
  actionType = 'BOOK_APPOINTMENT';
}

return {
  json: {
    replyText,
    intent,
    suggestedAction: {
      actionType,
      metadata: {
        doctorId: item.doctorId,
        doctorName: item.doctorName
      }
    }
  }
};
